package com.blog.service.impl; import com.blog.dto.*; import com.blog.dto.PostDtos.*; import com.blog.entity.*; import com.blog.exception.ApiExceptions.*; import com.blog.mapper.BlogMapper; import com.blog.repository.*; import com.blog.service.BlogServices.PostService; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.text.Normalizer;
@Service @RequiredArgsConstructor @Transactional public class PostServiceImpl implements PostService {private final PostRepository posts;private final UserRepository users;private final CategoryRepository categories;private final BlogMapper mapper; public PostResponse create(PostRequest r,String email){var p=Post.builder().author(user(email)).slug(uniqueSlug(r.title())).build();apply(p,r);return mapper.post(posts.save(p));} @Transactional(readOnly=true) public PageResponse<PostResponse> findAll(Long categoryId,Pageable p){Page<Post> result=categoryId==null?posts.findAll(p):posts.findByCategoryId(categoryId,p);return PageResponse.of(result.map(mapper::post));} @Transactional(readOnly=true) public PostResponse findById(Long id){return mapper.post(post(id));} public PostResponse update(Long id,PostRequest r,String email){var p=post(id);owner(p,email);apply(p,r);return mapper.post(p);} public void delete(Long id,String email){var p=post(id);owner(p,email);posts.delete(p);} @Transactional(readOnly=true) public PageResponse<PostResponse> search(String keyword,Pageable p){if(keyword==null||keyword.isBlank())throw new BadRequestException("Keyword is required");return PageResponse.of(posts.search(keyword,p).map(mapper::post));} private void apply(Post p,PostRequest r){p.setTitle(r.title());p.setContent(r.content());p.setImageUrl(r.imageUrl());p.setPublished(r.published());p.setCategory(r.categoryId()==null?null:categories.findById(r.categoryId()).orElseThrow(()->new ResourceNotFoundException("Category not found")));} private User user(String email){return users.findByEmail(email).orElseThrow(()->new ResourceNotFoundException("User not found"));} private Post post(Long id){return posts.findById(id).orElseThrow(()->new ResourceNotFoundException("Post not found"));} private void owner(Post p,String email){var u=user(email);if(u.getRole()!=Role.ADMIN&&!p.getAuthor().getId().equals(u.getId()))throw new UnauthorizedException("You do not own this post");} private String uniqueSlug(String title){String base=Normalizer.normalize(title,Normalizer.Form.NFD).replaceAll("[^\\p{ASCII}]","").toLowerCase().replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");String candidate=base;int n=2;while(slugExists(candidate)) candidate=base+"-"+n++;return candidate;} private boolean slugExists(String slug){return posts.findAll().stream().map(Post::getSlug).anyMatch(slug::equals);} }
